#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum NamedColor {
    Black, Red, Green, Yellow, Blue, Magenta, Cyan, White,
}
impl NamedColor {
    fn from_str_insensitive(s: &str) -> Option<Self> {
        if s.eq_ignore_ascii_case("black") { Some(Self::Black) }
        else if s.eq_ignore_ascii_case("red") { Some(Self::Red) }
        else if s.eq_ignore_ascii_case("green") { Some(Self::Green) }
        else if s.eq_ignore_ascii_case("yellow") { Some(Self::Yellow) }
        else if s.eq_ignore_ascii_case("blue") { Some(Self::Blue) }
        else if s.eq_ignore_ascii_case("magenta") { Some(Self::Magenta) }
        else if s.eq_ignore_ascii_case("cyan") { Some(Self::Cyan) }
        else if s.eq_ignore_ascii_case("white") { Some(Self::White) }
        else { None }
    }
    fn to_num(self) -> u8 {
        match self {
            Self::Black => 0,
            Self::Red => 1,
            Self::Green => 2,
            Self::Yellow => 3,
            Self::Blue => 4,
            Self::Magenta => 5,
            Self::Cyan => 6,
            Self::White => 7,
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Color {
    Named(NamedColor),
    Ansi256(u8),
    Rgb(u8,u8,u8),
}

#[derive(Clone, Debug)]
struct Face {
    fg: Option<Color>,
    bg: Option<Color>,
    bold: bool,
    italic: bool,
    dimmed: bool,
    intense: bool,
    underline: bool,
}
impl Face {
    fn empty() -> Self {
        Self { fg: None, bg: None, bold: false, italic: false, dimmed: false, intense: false, underline: false }
    }
    fn to_ansi(&self) -> Vec<u8> {
        let mut out = Vec::new();
        if self.bold { out.extend_from_slice(b"\x1b[1m"); }
        if self.dimmed { out.extend_from_slice(b"\x1b[2m"); }
        if self.italic { out.extend_from_slice(b"\x1b[3m"); }
        if self.underline { out.extend_from_slice(b"\x1b[4m"); }
        if let Some(fg) = self.fg {
            match fg {
                Color::Named(n) => {
                    let num = n.to_num();
                    if self.intense {
                        out.extend_from_slice(format!("\x1b[38;5;{}m", num+8).as_bytes());
                    } else {
                        out.extend_from_slice(format!("\x1b[{}m", 30+num as u8).as_bytes());
                    }
                }
                Color::Ansi256(v) => {
                    out.extend_from_slice(format!("\x1b[38;5;{}m", v).as_bytes());
                }
                Color::Rgb(r,g,b) => {
                    out.extend_from_slice(format!("\x1b[38;2;{};{};{}m", r,g,b).as_bytes());
                }
            }
        }
        if let Some(bg) = self.bg {
            match bg {
                Color::Named(n) => {
                    let num = n.to_num();
                    if self.intense {
                        out.extend_from_slice(format!("\x1b[48;5;{}m", num+8).as_bytes());
                    } else {
                        out.extend_from_slice(format!("\x1b[{}m", 40+num as u8).as_bytes());
                    }
                }
                Color::Ansi256(v) => {
                    out.extend_from_slice(format!("\x1b[48;5;{}m", v).as_bytes());
                }
                Color::Rgb(r,g,b) => {
                    out.extend_from_slice(format!("\x1b[48;2;{};{};{}m", r,g,b).as_bytes());
                }
            }
        }
        out
    }
}

fn default_faces() -> (Face, Face, Face, Face) {
    // added, removed, refine-added, refine-removed
