}

fn is_hex_digit(b: u8) -> bool {
    (b >= b'0' && b <= b'9') || (b >= b'a' && b <= b'f') || (b >= b'A' && b <= b'F')
}
fn is_all_hex(s: &str) -> bool {
    if s.is_empty() { return true; }
    s.bytes().all(|b| is_hex_digit(b))
}

fn parse_u8_decimal(s: &str) -> Option<u8> {
    // Allows leading '+' (like Rust's u8::from_str), leading zeros, no '-', no spaces, 0..255
    // Use Rust's parse for u8 which allows '+'? Actually "0".parse::<u8>() allows '+'? Let's test: "+1".parse::<u8>() succeeds in Rust (allows '+'). Good. So we can just use s.parse::<u8>()? But s.parse::<u8>() for "+256" fails (out of range), for "256" fails, for "" fails, for " 1" fails (spaces), for "+ 1" fails, etc. Good. For "00", "01", etc. succeeds. Good. For "+0x10", fails (invalid digit). Good.
    // However, s.parse::<u8>() for "0x10" fails (since 'x' invalid digit). Good (hex handled separately).
    // So just use parse.
    s.parse::<u8>().ok()
}
fn parse_u8_hex(s: &str) -> Option<u8> {
    // Must start with "0x" (lowercase x only), no '+', hex digits case-insensitive, value 0..255, non-empty after prefix
    if !s.starts_with("0x") { return None; }
    let hex = &s[2..];
    if hex.is_empty() { return None; }
    if !hex.bytes().all(|b| is_hex_digit(b)) { return None; }
    // Parse as hex u32 then check <=255? Need to handle leading zeros and large values (e.g., "0x000ff" (5 hex digits, value 255) valid? Earlier "0x00ff" (4 hex digits, value 255) valid. "0x000ff" (5 hex digits? Actually "0x000ff" is 0x + 5 hex digits? No, "0x000ff" is 0x + 5? Let's count: "0x000ff" after prefix "000ff" (5 hex digits), value 255, valid. Good. "0xFFFF" (4 hex digits, value 65535>255) invalid. Good. So parse as u32 then check <=255.
    // Also need to handle very long hex (e.g., "0xffffffff" (8 hex digits, value 4294967295>255) invalid. Good.
    // Use u32::from_str_radix?
    match u32::from_str_radix(hex, 16) {
        Ok(v) if v <= 255 => Some(v as u8),
        _ => None,
    }
}
fn parse_u8_component(s: &str) -> Option<u8> {
    // For RGB components and single decimal/hex? Actually single decimal/hex uses same? For single, decimal allows '+', hex requires 0x. For RGB components, same? Earlier "+1" valid for RGB components (e.g., "+1,+2,+3" valid). Good. So same.
    // Try decimal first? Or hex? Order? For "0x10", decimal fails (since 'x'), hex succeeds. For "10", decimal succeeds (10), hex fails (since doesn't start with 0x). Good. For "+0x10", decimal fails (since 'x'), hex fails (since doesn't start with 0x, starts with '+'), so None. Good.
    if let Some(v) = parse_u8_decimal(s) {
        return Some(v);
    }
    if let Some(v) = parse_u8_hex(s) {
        return Some(v);
    }
    None
}

fn parse_color_value(s: &str) -> Result<Option<Color>, String> {
    // Returns Ok(Some(color)) for valid color, Ok(None) for "none" (clear), Err(message) for invalid (full message without trailing \n? Actually messages end with \n, we'll add \n when printing)
    // s is color string (after foreground:/background:)
    if s == "none" {
        return Ok(None);
    }
    if s.contains(',') {
        // RGB triple
        let parts: Vec<&str> = s.split(',').collect();
        if parts.len() != 3 {
            return Err(format!("unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'", s));
        }
        let mut vals = [0u8;3];
        for (i, part) in parts.iter().enumerate() {
            if let Some(v) = parse_u8_component(part) {
                vals[i]=v;
            } else {
                return Err(format!("unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'", s));
            }
        }
        return Ok(Some(Color::Rgb(vals[0], vals[1], vals[2])));
    } else {
        // Single: try named (case-insensitive for 8 colors, case-sensitive "none" already handled)
        if let Some(n) = NamedColor::from_str_insensitive(s) {
            return Ok(Some(Color::Named(n)));
        }
        // Try decimal/hex? Actually need to distinguish valid vs invalid for error type? For valid, return color. For invalid, error type depends on hex check.
        // Try decimal/hex parsing for valid?
        // For single, valid decimal/hex are same as components? e.g., "0".."255" with '+'? "+12" valid (as observed, "+12" valid for single). Good. "0x10" valid. Good.
        if let Some(v) = parse_u8_component(s) {
            // Need to distinguish Named vs Ansi256? Actually decimal/hex single values are Ansi256 (0..255), not Named (even for 0..7, they are Ansi256, not Named, as observed, "0" gives 38;5;0, not 30). Good. So return Ansi256.
            return Ok(Some(Color::Ansi256(v)));
        }
        // Invalid: decide error type based on hex check
        if is_all_hex(s) {
            return Err(format!("unexpected color value: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{}'", s));
        } else {
            return Err(format!("unexpected color value: unrecognized color name '{}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white", s));
        }
    }
}

fn apply_color_spec(spec: &str, added: &mut Face, removed: &mut Face, refine_added: &mut Face, refine_removed: &mut Face) -> Result<(), String> {
    // Split by ':' into parts (keep empty? Rust's split(':') splits on each ':', keeping empty between and trailing? For "added:" => ["added",""] (2). For "added" (no colon) => ["added"] (1). Good. For "" => [""] (1). Good.
    let parts: Vec<&str> = spec.split(':').collect();
    let face_name = parts[0];
    let face: &mut Face = match face_name {
        "added" => added,
        "removed" => removed,
        "refine-added" => refine_added,
        "refine-removed" => refine_removed,
        _ => return Err(format!("unexpected face name: got '{}', expected added|refine-added|removed|refine-removed", face_name)),
    };
    if parts.len() == 1 {
        // No attributes (just face, e.g., "added" with no colon) => no-op, valid
        return Ok(());
    }
    // Attributes parts are parts[1..]
    let attrs = &parts[1..];
    let mut i = 0;
    while i < attrs.len() {
        let attr = attrs[i];
        if attr == "foreground" || attr == "background" {
            if i+1 >= attrs.len() {
                return Err(format!("error parsing color: missing color value for face '{}'", face_name));
            }
            let color_str = attrs[i+1];
            match parse_color_value(color_str) {
                Ok(opt_color) => {
                    if attr == "foreground" {
                        face.fg = opt_color;
                    } else {
                        face.bg = opt_color;
                    }
                }
                Err(msg) => return Err(msg),
            }
            i += 2;
        } else if attr == "italic" { face.italic = true; i+=1; }
        else if attr == "noitalic" { face.italic = false; i+=1; }
        else if attr == "bold" { face.bold = true; i+=1; }
        else if attr == "nobold" { face.bold = false; i+=1; }
        else if attr == "dimmed" { face.dimmed = true; i+=1; }
        else if attr == "nodimmed" { face.dimmed = false; i+=1; }
        else if attr == "intense" { face.intense = true; i+=1; }
        else if attr == "nointense" { face.intense = false; i+=1; }
        else if attr == "underline" { face.underline = true; i+=1; }
        else if attr == "nounderline" { face.underline = false; i+=1; }
        else if attr == "none" {
            // Clear all
            face.fg = None;
            face.bg = None;
            face.bold = false;
            face.italic = false;
            face.dimmed = false;
            face.intense = false;
            face.underline = false;
            i+=1;
        } else {
            return Err(format!("unexpected attribute name: got '{}', expected foreground|background|italic|noitalic|bold|nobold|dimmed|nodimmed|intense|nointense|underline|nounderline|none", attr));
        }
    }
    Ok(())
}

