fn apply_color_spec(spec: &str, added: &mut Face, removed: &mut Face, refine_added: &mut Face, refine_removed: &mut Face) -> Result<(), String> {
    // Split by ':' into parts (keep empty? Rust's split(':') splits on each ':', keeping empty between and trailing? For "added:" => ["added",""] (2). For "added" (no colon) => ["added"] (1). Good. For "" => [""] (1). Good.
    let parts: Vec<&str> = spec.split(':').collect();
    let face_name = parts[0];
    let face: &mut Face = match face_name {
        "added" => added,
        "removed" => removed,
        "refine-added" => refine_added,
        "refine-removed" => refine_removed,
        _ => return Err(format!("unexpected face name: got '{}', expected added|refine-added|removed|refine-removed", face_name)),
    };
    if parts.len() == 1 {
        // No attributes (just face, e.g., "added" with no colon) => no-op, valid
        return Ok(());
    }
    // Attributes parts are parts[1..]
    let attrs = &parts[1..];
    let mut i = 0;
    while i < attrs.len() {
        let attr = attrs[i];
        if attr == "foreground" || attr == "background" {
            if i+1 >= attrs.len() {
                return Err(format!("error parsing color: missing color value for face '{}'", face_name));
            }
            let color_str = attrs[i+1];
            match parse_color_value(color_str) {
                Ok(opt_color) => {
                    if attr == "foreground" {
                        face.fg = opt_color;
                    } else {
                        face.bg = opt_color;
                    }
                }
                Err(msg) => return Err(msg),
            }
            i += 2;
        } else if attr == "italic" { face.italic = true; i+=1; }
        else if attr == "noitalic" { face.italic = false; i+=1; }
        else if attr == "bold" { face.bold = true; i+=1; }
        else if attr == "nobold" { face.bold = false; i+=1; }
        else if attr == "dimmed" { face.dimmed = true; i+=1; }
        else if attr == "nodimmed" { face.dimmed = false; i+=1; }
        else if attr == "intense" { face.intense = true; i+=1; }
        else if attr == "nointense" { face.intense = false; i+=1; }
        else if attr == "underline" { face.underline = true; i+=1; }
        else if attr == "nounderline" { face.underline = false; i+=1; }
        else if attr == "none" {
            // Clear all
            face.fg = None;
            face.bg = None;
            face.bold = false;
            face.italic = false;
            face.dimmed = false;
            face.intense = false;
            face.underline = false;
            i+=1;
        } else {
            return Err(format!("unexpected attribute name: got '{}', expected foreground|background|italic|noitalic|bold|nobold|dimmed|nodimmed|intense|nointense|underline|nounderline|none", attr));
        }
    }
    Ok(())
}

