fn write_plain_line(out: &mut impl Write, content: &[u8], has_newline: bool) -> std::io::Result<()> {
    out.write_all(b"\x1b[0m")?;
    out.write_all(content)?;
    out.write_all(b"\x1b[0m")?;
    if has_newline {
