{"command":"cat >> src/main.rs <<'RS'
struct HL { raw: Vec<u8>, has_newline: bool, prefix: u8 }
fn process_lines(lines: &[(Vec<u8>, bool)], line_numbers: Option<LineNumbersStyle>, added_face: &Face, removed_face: &Face, refine_added_face: &Face, refine_removed_face: &Face) -> Result<(), ()> {
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    let added_ansi = added_face.to_ansi();
    let removed_ansi = removed_face.to_ansi();
    let refine_added_ansi = refine_added_face.to_ansi();
    let refine_removed_ansi = refine_removed_face.to_ansi();
    let red_bg: &[u8] = b"\x1b[41m";
    let mut in_hunk = false;
    let mut hunk_header: (u64,u64,u64,u64) = (0,0,0,0);
    let mut hunk_buf: Vec<HL> = Vec::new();
    let mut idx = 0usize;
    while idx < lines.len() {
        let (raw, hn) = &lines[idx];
        let first: Option<u8> = if raw.is_empty() { None } else { Some(raw[0]) };
        if first == Some(b'@') {
            if in_hunk {
                if let Err(()) = flush_one_hunk(&mut out, hunk_header, &hunk_buf, line_numbers, added_face, removed_face, &added_ansi, &removed_ansi, &refine_added_ansi, &refine_removed_ansi, red_bg) { return Err(()); }
                hunk_buf.clear();
            }
            out.write_all(b"\x1b[0m").map_err(|_| ())?;
            out.write_all(raw).map_err(|_| ())?;
            out.write_all(b"\x1b[0m").map_err(|_| ())?;
            if *hn { out.write_all(b"\n").map_err(|_| ())?; }
            if line_numbers.is_some() { hunk_header = parse_hunk_header(raw); } else { hunk_header = (0,0,0,0); }
            in_hunk = true;
            idx += 1;
        } else if in_hunk && (first == Some(b' ') || first == Some(b'-') || first == Some(b'+') || first == Some(b'\\')) {
            hunk_buf.push(HL{ raw: raw.clone(), has_newline: *hn, prefix: first.unwrap() });
            idx += 1;
        } else {
            if in_hunk {
                if let Err(()) = flush_one_hunk(&mut out, hunk_header, &hunk_buf, line_numbers, added_face, removed_face, &added_ansi, &removed_ansi, &refine_added_ansi, &refine_removed_ansi, red_bg) { return Err(()); }
                hunk_buf.clear();
                in_hunk = false;
            }
            out.write_all(b"\x1b[0m").map_err(|_| ())?;
            out.write_all(raw).map_err(|_| ())?;
            out.write_all(b"\x1b[0m").map_err(|_| ())?;
            if *hn { out.write_all(b"\n").map_err(|_| ())?; }
            idx += 1;
        }
    }
    if in_hunk {
        if let Err(()) = flush_one_hunk(&mut out, hunk_header, &hunk_buf, line_numbers, added_face, removed_face, &added_ansi, &removed_ansi, &refine_added_ansi, &refine_removed_ansi, red_bg) { return Err(()); }
    }
    out.flush().map_err(|_| ())?;
    Ok(())
}
RS
